def parity_gap(c, p, S, K, r, T):
    """Call side minus put side of parity."""
    return c + K / (1 + r) ** T - (p + S)

def flag(quotes, S, r, T, tol=0.05):
    """Strikes whose gap is bigger than tol either way.
    quotes is a list of (K, c, p) tuples."""
    return [K for K, c, p in quotes
            if abs(parity_gap(c, p, S, K, r, T)) > tol]
